<?php

declare(strict_types=1);

namespace Te4g\UserBundle\Tools;

final class ShadcnSnapshotSynchronizer
{
    private const array ALLOWED_RECIPES = [
        'card',
        'button',
        'input',
        'field',
        'alert',
        'separator',
        'alert-dialog',
        'spinner',
    ];

    private const array FIXED_ICONS = [
        'circle-check',
        'eye',
        'eye-off',
        'key-round',
        'mail',
        'trash-2',
        'triangle-alert',
    ];

    /**
     * Synchronize files generated by a real UX Toolkit fixture.
     *
     * UX Toolkit 3.3 accepts one recipe per ux:install invocation. The caller
     * must run the eight fixed commands before invoking this synchronizer.
     *
     * @param list<string> $recipes
     *
     * @return array{
     *     schema_version: int,
     *     generated_by: string,
     *     upstream: array{package: string, version: string, reference: string, license: string},
     *     recipes: list<string>,
     *     compatibility: string,
     *     icons: array{package: string, version: string, license: string, names: list<string>},
     *     files: list<array{path: string, source: string, license: string, sha256: string}>
     * }
     */
    public function synchronize(string $projectRoot, string $destinationRoot, array $recipes = self::ALLOWED_RECIPES): array
    {
        $sourceRoot = $this->realDirectory($projectRoot, 'temporary project root');
        $destinationRoot = $this->createAndResolveDirectory($destinationRoot);
        $recipes = $this->validateRecipes($recipes);
        $package = $this->toolkitPackage($sourceRoot);
        $files = [];
        $visited = [];

        foreach ($recipes as $recipe) {
            $this->collectRecipeFiles($sourceRoot, $destinationRoot, $recipe, $visited, $files);
        }

        foreach (self::FIXED_ICONS as $icon) {
            $path = 'assets/icons/lucide/'.$icon.'.svg';
            $this->copyInstalledFile($sourceRoot, $destinationRoot, $path, null);
            $files[$path] = [
                'path' => $path,
                'source' => '@iconify-json/lucide@1.2.121',
                'license' => 'ISC',
                'sha256' => $this->hash($destinationRoot.'/'.$path),
            ];
        }

        ksort($files, SORT_STRING);
        $manifest = [
            'schema_version' => 1,
            'generated_by' => 'tools/ShadcnSnapshotSynchronizer.php',
            'upstream' => [
                'package' => 'symfony/ux-toolkit',
                'version' => ltrim($package['version'], 'v'),
                'reference' => $package['reference'],
                'license' => $package['license'],
            ],
            'recipes' => $recipes,
            'compatibility' => 'UX Toolkit 3.3 accepts one recipe per ux:install command; the fixed recipes are installed sequentially.',
            'icons' => [
                'package' => '@iconify-json/lucide',
                'version' => '1.2.121',
                'license' => 'ISC',
                'names' => self::FIXED_ICONS,
            ],
            'files' => array_values($files),
        ];

        $manifestDirectory = dirname($destinationRoot).'/shadcn';
        $this->assertDestinationPath($manifestDirectory, dirname($destinationRoot));
        if (!is_dir($manifestDirectory) && !mkdir($manifestDirectory, 0777, true) && !is_dir($manifestDirectory)) {
            throw new \RuntimeException('Unable to create the Shadcn manifest directory.');
        }

        $json = json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR)."\n";
        if (false === file_put_contents($manifestDirectory.'/manifest.json', $json)) {
            throw new \RuntimeException('Unable to write the Shadcn manifest.');
        }

        return $manifest;
    }

    /** @param list<string> $recipes
     * @return list<string>
     */
    private function validateRecipes(array $recipes): array
    {
        $validated = [];
        foreach ($recipes as $recipe) {
            if (!is_string($recipe) || !in_array($recipe, self::ALLOWED_RECIPES, true)) {
                throw new \InvalidArgumentException(sprintf('Unsupported Shadcn recipe "%s".', is_scalar($recipe) ? (string) $recipe : get_debug_type($recipe)));
            }

            if (!in_array($recipe, $validated, true)) {
                $validated[] = $recipe;
            }
        }

        return $validated;
    }

    /**
     * @param array<string, true>                                                                 $visited
     * @param array<string, array{path: string, source: string, license: string, sha256: string}> $files
     */
    private function collectRecipeFiles(
        string $sourceRoot,
        string $destinationRoot,
        string $recipe,
        array &$visited,
        array &$files,
    ): void {
        if (isset($visited[$recipe])) {
            return;
        }

        $visited[$recipe] = true;
        $recipeRoot = $sourceRoot.'/vendor/symfony/ux-toolkit/kits/shadcn/'.$this->safeRelativePath($recipe);
        $recipeRoot = $this->realDirectory($recipeRoot, 'recipe root');
        $manifestPath = $recipeRoot.'/manifest.json';
        $this->assertExistingFileInside($manifestPath, $sourceRoot, 'recipe manifest');
        $manifest = json_decode((string) file_get_contents($manifestPath), true, flags: JSON_THROW_ON_ERROR);

        if (!is_array($manifest)) {
            throw new \RuntimeException(sprintf('Invalid manifest for Shadcn recipe "%s".', $recipe));
        }

        $dependencies = $manifest['dependencies']['recipe'] ?? [];
        if (!is_array($dependencies)) {
            throw new \RuntimeException(sprintf('Invalid recipe dependencies for "%s".', $recipe));
        }

        foreach ($dependencies as $dependency) {
            if (!is_string($dependency) || 1 !== preg_match('/^[a-z0-9-]+$/D', $dependency)) {
                throw new \RuntimeException('Unsafe snapshot path in recipe dependency.');
            }

            $this->collectRecipeFiles($sourceRoot, $destinationRoot, $dependency, $visited, $files);
        }

        $copyFiles = $manifest['copy-files'] ?? null;
        if (!is_array($copyFiles)) {
            throw new \RuntimeException(sprintf('Recipe "%s" has no copy-files map.', $recipe));
        }

        foreach ($copyFiles as $from => $to) {
            if (!is_string($from) || !is_string($to)) {
                throw new \RuntimeException('Unsafe snapshot path in recipe copy map.');
            }

            $from = $this->safeRelativePath($from);
            $to = $this->safeRelativePath($to);
            $recipeSource = $recipeRoot.'/'.$from;
            $recipeSource = $this->realDirectory($recipeSource, 'recipe copy source');
            $iterator = new \RecursiveIteratorIterator(
                new \RecursiveDirectoryIterator($recipeSource, \FilesystemIterator::SKIP_DOTS),
            );

            /** @var \SplFileInfo $item */
            foreach ($iterator as $item) {
                if (!$item->isFile()) {
                    continue;
                }

                $upstreamPath = $item->getPathname();
                $this->assertExistingFileInside($upstreamPath, $sourceRoot, 'recipe source');
                $suffix = substr($upstreamPath, strlen($recipeSource) + 1);
                $targetPath = $this->safeRelativePath($to.'/'.$suffix);
                $installedPath = $sourceRoot.'/'.$targetPath;
                $this->copyInstalledFile($sourceRoot, $destinationRoot, $targetPath, $upstreamPath);
                $files[$targetPath] = [
                    'path' => $targetPath,
                    'source' => 'symfony/ux-toolkit:shadcn/'.$recipe,
                    'license' => 'MIT',
                    'sha256' => $this->hash($destinationRoot.'/'.$targetPath),
                ];

                if (!hash_equals($this->hash($upstreamPath), $this->hash($installedPath))) {
                    throw new \RuntimeException(sprintf('Installed recipe file "%s" differs from the pinned upstream recipe.', $targetPath));
                }
            }
        }
    }

    private function copyInstalledFile(string $sourceRoot, string $destinationRoot, string $relativePath, ?string $upstreamPath): void
    {
        $relativePath = $this->safeRelativePath($relativePath);
        $source = $sourceRoot.'/'.$relativePath;
        $this->assertExistingFileInside($source, $sourceRoot, 'installed source');
        if (null !== $upstreamPath) {
            $this->assertExistingFileInside($upstreamPath, $sourceRoot, 'upstream source');
        }

        $destination = $destinationRoot.'/'.$relativePath;
        $this->assertDestinationPath($destination, $destinationRoot);
        $parent = dirname($destination);
        if (!is_dir($parent) && !mkdir($parent, 0777, true) && !is_dir($parent)) {
            throw new \RuntimeException(sprintf('Unable to create snapshot directory "%s".', $relativePath));
        }

        $this->assertDestinationPath($destination, $destinationRoot);
        if (!copy($source, $destination)) {
            throw new \RuntimeException(sprintf('Unable to copy snapshot file "%s".', $relativePath));
        }
    }

    /** @return array{version: string, reference: string, license: string} */
    private function toolkitPackage(string $sourceRoot): array
    {
        $installedPath = $sourceRoot.'/vendor/composer/installed.json';
        $this->assertExistingFileInside($installedPath, $sourceRoot, 'Composer installed metadata');
        $installed = json_decode((string) file_get_contents($installedPath), true, flags: JSON_THROW_ON_ERROR);
        $packages = is_array($installed) && isset($installed['packages']) && is_array($installed['packages'])
            ? $installed['packages']
            : $installed;

        if (!is_array($packages)) {
            throw new \RuntimeException('Invalid Composer installed metadata.');
        }

        foreach ($packages as $package) {
            if (!is_array($package) || 'symfony/ux-toolkit' !== ($package['name'] ?? null)) {
                continue;
            }

            $version = $package['version'] ?? null;
            $reference = $package['source']['reference'] ?? $package['dist']['reference'] ?? null;
            $license = $package['license'][0] ?? null;
            if (!is_string($version) || !is_string($reference) || !is_string($license)) {
                break;
            }

            return ['version' => $version, 'reference' => $reference, 'license' => $license];
        }

        throw new \RuntimeException('Unable to resolve the installed symfony/ux-toolkit package metadata.');
    }

    private function safeRelativePath(string $path): string
    {
        if ('' === $path || str_contains($path, "\0")) {
            throw new \RuntimeException('Unsafe snapshot path.');
        }

        $portable = str_replace('\\', '/', $path);
        if (str_starts_with($portable, '/') || 1 === preg_match('/^[A-Za-z]:\//', $portable)) {
            throw new \RuntimeException('Unsafe snapshot path.');
        }

        $segments = [];
        foreach (explode('/', $portable) as $segment) {
            if ('' === $segment || '.' === $segment) {
                continue;
            }

            if ('..' === $segment) {
                throw new \RuntimeException('Unsafe snapshot path.');
            }

            $segments[] = $segment;
        }

        if ([] === $segments) {
            throw new \RuntimeException('Unsafe snapshot path.');
        }

        return implode('/', $segments);
    }

    private function realDirectory(string $path, string $label): string
    {
        if (is_link($path) || false === ($resolved = realpath($path)) || !is_dir($resolved)) {
            throw new \RuntimeException(sprintf('Invalid %s.', $label));
        }

        return rtrim($resolved, DIRECTORY_SEPARATOR);
    }

    private function createAndResolveDirectory(string $path): string
    {
        if (is_link($path)) {
            throw new \RuntimeException('Snapshot destination escapes the snapshot destination root.');
        }

        if (!is_dir($path) && !mkdir($path, 0777, true) && !is_dir($path)) {
            throw new \RuntimeException('Unable to create the snapshot destination.');
        }

        return $this->realDirectory($path, 'snapshot destination');
    }

    private function assertExistingFileInside(string $path, string $root, string $label): void
    {
        if (is_link($path) || false === ($resolved = realpath($path)) || !is_file($resolved) || !$this->contains($resolved, $root)) {
            throw new \RuntimeException(sprintf('%s escapes the temporary project root.', ucfirst($label)));
        }
    }

    private function assertDestinationPath(string $path, string $root): void
    {
        $root = rtrim($root, DIRECTORY_SEPARATOR);
        if (!$this->contains($path, $root)) {
            throw new \RuntimeException('Snapshot destination escapes the snapshot destination root.');
        }

        $relative = ltrim(substr($path, strlen($root)), DIRECTORY_SEPARATOR);
        $current = $root;
        foreach (array_filter(explode(DIRECTORY_SEPARATOR, $relative), static fn (string $part): bool => '' !== $part) as $part) {
            $current .= DIRECTORY_SEPARATOR.$part;
            if (is_link($current)) {
                throw new \RuntimeException('Snapshot destination escapes the snapshot destination root.');
            }
        }
    }

    private function contains(string $path, string $root): bool
    {
        $root = rtrim($root, DIRECTORY_SEPARATOR);

        return $path === $root || str_starts_with($path, $root.DIRECTORY_SEPARATOR);
    }

    private function hash(string $path): string
    {
        $hash = hash_file('sha256', $path);
        if (false === $hash) {
            throw new \RuntimeException(sprintf('Unable to hash snapshot file "%s".', $path));
        }

        return $hash;
    }
}
